// ── Regular Expression Fundamentals ─────────────────────────────
// Every regex compiles to an NFA which compiles to a DFA.
// We demonstrate the three core operations and common sugar.

// BASE CASES
const empty  = /(?!)/;   // matches nothing (empty language)
const eps    = /^$/;      // matches only empty string
const litA   = /^a$/;    // matches only the symbol 'a'

// CONCATENATION: r then s
const ab     = /^ab$/;                    // L = {"ab"}
const digits = /^\d{3}-\d{2}-\d{4}$/;  // concatenation of digit groups and literals

// UNION: r | s
const color  = /^(gray|grey)$/;           // British or American spelling
const hex    = /^[0-9A-Fa-f]+$/;         // char class = large union over Sigma

// KLEENE STAR: r* (zero or more)
const aStar  = /^a*$/;                    // L = {ε, a, aa, aaa, ...}
const words  = /^[a-zA-Z]\w*$/;         // identifier: letter then zero or more word-chars

// SYNTACTIC SUGAR
const aPlus  = /^a+$/;                   // = /^aa*$/ (one or more a's)
const aOpt   = /^colou?r$/;              // colour or color (? = zero or one)
const bounded = /^\d{2,4}$/;             // 2 to 4 digits

// DEMO: test strings against the decimal number regex
const decimal = /^-?\d+(\.\d+)?$/;      // optional minus, digits, optional .digits
const tests = ['42', '-17', '3.14', '.5', '3.', '1e10', 'abc'];
console.log('Decimal number tests:');
for (const t of tests) {
  console.log(`  '${t}': ${decimal.test(t)}`);
}
// '42': true   '-17': true   '3.14': true
// '.5': false  '3.': false  '1e10': false  'abc': false

// HAND-ROLLED DFA for the same language (decimal numbers)
// States: 0=start 1=after-minus 2=integer-digits 3=dot 4=frac-digits(accept)
function isDecimalDFA(s) {
  let state = 0;
  for (const ch of s) {
    switch (state) {
      case 0:
        if (ch === '-')           state = 1;
        else if (/\d/.test(ch))  state = 2;
        else                     return false;
        break;
      case 1:
        state = /\d/.test(ch) ? 2 : -1;
        break;
      case 2:
        if (/\d/.test(ch))       state = 2;
        else if (ch === '.')     state = 3;
        else                     return false;
        break;
      case 3:
        state = /\d/.test(ch) ? 4 : -1;
        break;
      case 4:
        state = /\d/.test(ch) ? 4 : -1;
        break;
      default: return false;
    }
  }
  return state === 2 || state === 4; // integer or decimal
}

console.log('\nDFA vs regex agreement:');
for (const t of tests) {
  const rx  = decimal.test(t);
  const dfa = isDecimalDFA(t);
  console.log(`  '${t}': regex=${rx} dfa=${dfa} agree=${rx === dfa}`);
}

// ── Pumping Lemma Visualised in Code ─────────────────────────────
// We cannot write a DFA for {a^n b^n} — but we can demonstrate
// WHY every regex attempt fails by showing pumped strings escape the language.

// Correct membership check for {a^n b^n} requires COUNTING — not finite state
function isEqualAB(s) {
  // Must count: not doable with a pure regex/DFA
  const m = s.match(/^(a*)(b*)$/);
  if (!m) return false;
  return m[1].length === m[2].length;
}

// Demonstrate the pumping lemma argument:
function demonstratePumping(p) {
  const s = 'a'.repeat(p) + 'b'.repeat(p);   // choose s = a^p b^p
  console.log(`s = a^${p}b^${p} = '${s.slice(0, 10)}...' length=${s.length}`);
  console.log(`s in L? ${isEqualAB(s)}`); // must be true

  // Adversary tries all valid splits (|xy| <= p, |y| >= 1)
  // y must be within the first p characters (all a's)
  for (let j = 0; j < p; j++) {          // x = s[0..j)
    for (let k = 1; k <= p - j; k++) {   // y = s[j..j+k), |y|=k>=1
      const x = s.slice(0, j);
      const y = s.slice(j, j + k);
      const z = s.slice(j + k);

      // Pump y twice: xy^2 z
      const pumped = x + y + y + z;
      const inL    = isEqualAB(pumped);

      if (inL) {
        console.log(`  Split j=${j} k=${k}: xy^2z='${pumped.slice(0,12)}...' STILL in L (unexpected)`);
      } else {
        // This is the expected outcome — pumping breaks membership
        if (j === 0 && k === 1) { // show just the first failure for clarity
          console.log(`  Split j=${j} k=${k}: y='${y}', xy^2z has ${(x+y+y+z).match(/^a*/)[0].length} a's and ${(x+y+y+z).match(/b*$/)[0].length} b's`);
          console.log(`  xy^2z NOT in L: ${!inL} — pumping breaks it`);
        }
      }
    }
  }
  console.log(`Conclusion: no valid split survives pumping => L is NOT regular.`);
}

demonstreatePumping(5);

// ── What regex REQUIRES beyond regular languages ─────────────────
// Balanced brackets — context-free, needs a pushdown automaton
function isBalanced(s) {
  let depth = 0;                     // unbounded counter = memory beyond DFA
  for (const ch of s) {
    if (ch === '(')      depth++;
    else if (ch === ')') depth--;
    if (depth < 0)       return false;
  }
  return depth === 0;
}

// Palindromes — context-free
function isPalindrome(s) {
  return s === s.split('').reverse().join('');
}

console.log(isBalanced('((()))'));  // true
console.log(isBalanced('(())())'));  // false
console.log(isPalindrome('racecar')); // true

// ── What regex CAN and CANNOT do: a decision guide ──────────────

// REGULAR (DFA-safe, O(n) time):
const examples = [
  { r: /^[A-Z][a-z]{1,20}$/, note: 'Capitalised English name' },
  { r: /^\d{4}-\d{2}-\d{2}$/, note: 'ISO date yyyy-mm-dd' },
  { r: /^[01]+$/, note: 'Binary string' },
  { r: /^(https?:\/\/)[\w./-]+$/, note: 'URL with protocol' },
  { r: /^[\w.+-]+@[\w-]+\.[a-z]{2,}$/i, note: 'Email shape (not validity)' },
];

// NOT REGULAR — do NOT use regex alone:
// 1. Balanced brackets:  (((x))) — use a parser
// 2. Palindromes: aba, racecar — use string reversal
// 3. Equal counts: a^n b^n — use counting
// 4. Matching HTML tags: <div>...</div> with arbitrary nesting — use a DOM parser
// 5. Self-referential patterns: backreference (\w+)\s+\1 — use NLP/tokeniser

// DANGEROUS PATTERNS (catastrophic backtracking):
// (a+)+  on 'aaaa...aab' — exponential
// (a|aa)+ on 'aaaa...b'  — exponential
// (.*a){20} on long non-matching string — exponential

// SAFE EQUIVALENTS:
const safeAPlus  = /a+/;      // never nest the same quantifier
const safeOrMore = /a+b/;     // anchor alternatives tightly

// RULE OF THUMB:
// If your pattern needs to 'remember' something of unbounded length, it's not regular.
// Use a parser, not a regex.

// RE2 / linear-time engines ban:
//   - Backreferences: \1, \2, ...
//   - Lookahead/lookbehind (some RE2 variants allow fixed-length lookbehind)
// In return they guarantee O(m*n) worst-case time — no catastrophic backtracking.

console.log('Checking safe patterns:');
examples.forEach(({ r, note }) => {
  console.log(`  ${note}: ${r}`);
});
console.log('Always prefer RE2-style engines for untrusted input.');

// ReDoS (Regular Expression Denial of Service) example:
// Pattern: /^(a+)+$/ on input 'aaaaaaaaaaaaaaaab'
// A PCRE engine tries 2^16 paths. This is a real attack vector.
// Defence: use RE2, or test with redos-checker, or rewrite the pattern.
